package com.tduck.cloud.api.ai;

import com.tduck.cloud.form.ai.*;
import com.tduck.cloud.form.assistant.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import static com.tduck.cloud.form.analysis.AnalysisJson.*;

public class AssistantSimpleTest {
    private void reject(String text,String scope){try{AssistantPlanner.parseAutomatic(text,scope,null);fail("Untrusted reply accepted");}catch(IllegalArgumentException expected){}catch(com.tduck.cloud.common.exception.BaseException expected){}}
    @Test public void helloWorksWithoutAConfiguredProviderOrSurvey(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);Map<String,Object> r=new AssistantPlanner(p).automatic("你好",null,null,Collections.emptyList());assertEquals("chat",r.get("tool"));assertEquals("LOCAL",r.get("mode"));assertTrue(((Map<?,?>)r.get("arguments")).get("message").toString().contains("你好"));verifyNoInteractions(p);}
    @Test public void ordinaryChatUsesTheConfiguredModelAndRetainsAssistantHistory(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);when(p.available()).thenReturn(true);when(p.historyTurns()).thenReturn(2);when(p.complete(any(),any())).thenReturn("{\"tool\":\"chat\",\"arguments\":{\"message\":\"蓝光容易被散射。\"}}");Map<String,Object> r=new AssistantPlanner(p).automatic("再短一点",null,null,Arrays.asList(map("role","assistant","content","历史闲聊答复")));assertEquals("REAL",r.get("mode"));org.mockito.ArgumentCaptor<String> input=org.mockito.ArgumentCaptor.forClass(String.class);verify(p).complete(any(),input.capture());assertTrue(input.getValue().contains("历史闲聊答复"));}
    @Test public void modelCannotPutSurveyCountsInTheChatBranch(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);when(p.available()).thenReturn(true);when(p.complete(any(),any())).thenReturn("{\"tool\":\"chat\",\"arguments\":{\"message\":\"收了999份\"}}");Map<String,Object> r=new AssistantPlanner(p).automatic("回收多少答卷","owned",null,Collections.emptyList());assertEquals("survey_stats",r.get("tool"));assertFalse(r.toString().contains("999"));}
    @Test public void chatRepliesCannotSmuggleSqlOrOtherReplyFields(){reject("{\"tool\":\"chat\",\"arguments\":{\"message\":\"hello\",\"sql\":\"drop table\"}}",null);reject("{\"tool\":\"chat\",\"arguments\":{\"message\":\"hello\"},\"citations\":[\"fake\"]}",null);}
    @Test public void noSelectedScopeStillCannotReadArbitraryData(){reject("{\"tool\":\"survey_stats\",\"arguments\":{\"formKey\":\"foreign\"}}",null);}
    @Test public void duplicateChatJsonAndTrailingTextAreRejected(){reject("{\"tool\":\"chat\",\"tool\":\"chat\",\"arguments\":{\"message\":\"hi\"}}",null);reject("{\"tool\":\"chat\",\"arguments\":{\"message\":\"hi\"}}{}",null);}
    @Test public void implicitVersionGuessesAreDiscarded(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);when(p.available()).thenReturn(true);when(p.complete(any(),any())).thenReturn("{\"tool\":\"survey_stats\",\"arguments\":{\"formKey\":\"owned\",\"version\":999}}");Map<String,Object> r=new AssistantPlanner(p).automatic("查看最新统计","owned",1,Collections.emptyList());assertFalse(((Map<?,?>)r.get("arguments")).containsKey("version"));}
    @Test public void explicitVersionWorksWithoutAPicker(){assertEquals(Integer.valueOf(1),AssistantPlanner.versionHint("查V1的评分"));assertEquals(Integer.valueOf(2),AssistantPlanner.versionHint("版本2的统计"));}
    @Test public void surveyTerminologyCanStillBeOrdinaryConversation(){assertFalse(AssistantPlanner.needsData("什么是统计学"));assertFalse(AssistantPlanner.needsData("怎么设计问卷"));assertTrue(AssistantPlanner.needsData("我的问卷回收多少份"));}
    @Test public void selectedDeletionPreparesAProposalRatherThanClaimingSuccess(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);Map<String,Object> plan=new AssistantPlanner(p).automatic("把这份问卷移入回收站","owned",null,Collections.emptyList());assertEquals("manage_survey",plan.get("tool"));assertEquals("ARCHIVE",((Map<?,?>)plan.get("arguments")).get("action"));verifyNoInteractions(p);}
    @Test public void resolvedNamedSurveyCannotLoopBackIntoSearching(){Map<String,Object> p=AssistantPlanner.resolvedQuery("查找标题为“校园调查”的问卷V1回收多少答卷","owned",null,"校园调查");assertEquals("survey_stats",p.get("tool"));assertEquals(1,((Map<?,?>)p.get("arguments")).get("version"));}
    @Test public void followupStatisticsKeepTheSelectedHistoricalVersion(){Map<String,Object> p=new AssistantPlanner(mock(OpenAiCompatibleProvider.class)).automatic("那评分均值是多少？","owned",1,Collections.emptyList());assertEquals("survey_stats",p.get("tool"));assertEquals(1,((Map<?,?>)p.get("arguments")).get("version"));}
    @Test public void configuredHistoryLimitCountsExchangesRatherThanIndividualMessages(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);when(p.available()).thenReturn(true);when(p.historyTurns()).thenReturn(1);when(p.complete(any(),any())).thenReturn("{\"tool\":\"chat\",\"arguments\":{\"message\":\"好的\"}}");new AssistantPlanner(p).automatic("继续聊聊",null,null,Arrays.asList(map("user","older-exchange"),map("user","last-question","assistant","last-chat-reply")));org.mockito.ArgumentCaptor<String> input=org.mockito.ArgumentCaptor.forClass(String.class);verify(p).complete(any(),input.capture());assertFalse(input.getValue().contains("older-exchange"));assertTrue(input.getValue().contains("last-chat-reply"));}
    @Test public void outageKeepsDataQueriesWorkingAndDoesNotFakeGeneralReplies(){OpenAiCompatibleProvider p=mock(OpenAiCompatibleProvider.class);Map<String,Object> stats=new AssistantPlanner(p).automatic("回收数多少","owned",null,Collections.emptyList());assertEquals("survey_stats",stats.get("tool"));assertEquals("LOCAL",stats.get("mode"));Map<String,Object> chat=new AssistantPlanner(p).automatic("讲个笑话",null,null,Collections.emptyList());assertEquals("chat",chat.get("tool"));assertEquals("DEGRADED",chat.get("mode"));assertTrue(((Map<?,?>)chat.get("arguments")).get("message").toString().contains("暂时"));}
}
